/** Wraps a gate to count acquisitions and record each release outcome. */
const spyGate = (inner: MetadataLookupRateGate = immediateGate()) => {
    const record = { acquisitions: 0, releases: [] as ({ backoffMs?: number } | undefined)[] };
    const gate: MetadataLookupRateGate = {
        async acquire(source, mode, signal) {
            record.acquisitions++;
            const lease = await inner.acquire(source, mode, signal);
            return { sent: () => lease.sent(), release: async (outcome?: { backoffMs?: number }) => { record.releases.push(outcome); await lease.release(outcome); } } satisfies LookupGateLease;
        }
    };
    return { gate, record };
};
const spyCache = () => {
    const inner = createLookupResponseCache();
    const sets: string[] = [];
    const cache: LookupResponseCache = { get: key => inner.get(key), set: (key, value, bytes) => { sets.push(key); inner.set(key, value, bytes); }, clear: () => inner.clear() };
    return { cache, sets };
};
