test('Lucene escaping covers every special character and phrase terms join with AND in a fixed order', () => {
    for (const character of ['+', '-', '&', '|', '!', '(', ')', '{', '}', '[', ']', '^', '"', '~', '*', '?', ':', '\\', '/']) {
        assert.equal(escapeLucene(`a${character}b`), `a\\${character}b`, character);
    }
    assert.equal(escapeLucene('A && B || C'), 'A \\&\\& B \\|\\| C');
    assert.equal(musicBrainzLuceneQuery({ artist: 'AC/DC', release: 'Vol.1 ~Longing for the memorable days~' }),
        'release:"Vol.1 \\~Longing for the memorable days\\~" AND artist:"AC\\/DC"');
    assert.equal(musicBrainzLuceneQuery({ release: 'say "hi" \\ (live): x-y', tracks: 9, primarytype: 'album', secondarytype: 'audio drama' }),
        'release:"say \\"hi\\" \\\\ \\(live\\)\\: x\\-y" AND tracks:9 AND primarytype:"album" AND secondarytype:"audio drama"');
    // Terms keep a fixed order whatever the key order, so equal plans give equal URLs; a release search asks for a page of 100
    // releases (the run admits the plausible editions among them), a recording search for 25 recordings.
    const credited = { label: 'Asylum Records', artist: 'Eagles', release: 'Hotel California' };
    assert.equal(musicBrainzLuceneQuery(credited), 'release:"Hotel California" AND artist:"Eagles" AND label:"Asylum Records"');
    assert.equal(musicBrainzUrls.releaseSearch(credited).href, musicBrainzUrls.releaseSearch({ release: 'Hotel California', artist: 'Eagles', label: 'Asylum Records' }).href);
    assert.deepEqual([...musicBrainzUrls.releaseSearch(credited).searchParams.entries()].slice(1), [['fmt', 'json'], ['limit', '100']]);
    assert.equal(musicBrainzUrls.recordingSearch({ recording: 'パンドラコール' }).searchParams.get('limit'), '25');
    assert.equal(musicBrainzLuceneQuery({ barcode: '0 75596-05092 0', catno: '7559-60509-2' }), 'catno:"7559\\-60509\\-2" AND barcode:"075596050920"');
    assert.equal(musicBrainzLuceneQuery({ recording: 'パンドラコール', artist: 'ヰ世界情緒' }), 'recording:"パンドラコール" AND artist:"ヰ世界情緒"');
});

test('type filters are allowlisted and empty, over-long or link-like queries are refused', () => {
    for (const query of [{ release: 'x', primarytype: 'Album' }, { release: 'x', primarytype: 'bogus' }, { release: 'x', secondarytype: 'live"' },
        { release: 'x', tracks: 0 }, { release: 'x', tracks: 10_000 }, { release: 'x', tracks: 1.5 }, { barcode: '075596050921' }, { barcode: '0000000000000' }]) {
        assert.throws(() => musicBrainzLuceneQuery(query), inputFailure('identifier'), JSON.stringify(query));
    }
    assert.throws(() => musicBrainzLuceneQuery({}), inputFailure('empty'));
    assert.throws(() => musicBrainzLuceneQuery({ tracks: 9, primarytype: 'album' }), inputFailure('empty'));
    assert.throws(() => musicBrainzLuceneQuery({ release: '   ' }), inputFailure('empty'));
    assert.throws(() => musicBrainzLuceneQuery({ release: 'x'.repeat(201) }), inputFailure('tooLong'));
    assert.throws(() => musicBrainzLuceneQuery({ release: '-'.repeat(200), artist: '-'.repeat(200) }), inputFailure('tooLong'));
    for (const text of ['https://musicbrainz.org/release/x', 'www.example.test', 'javascript:alert(1)', 'see ftp://x', 'mailto:a']) {
        assert.throws(() => musicBrainzLuceneQuery({ release: text }), inputFailure('url'), text);
    }
    assert.throws(() => musicBrainzLuceneQuery({ release: `a${String.fromCharCode(0x200b)}b` }), inputFailure('invalidText'));
    assert.throws(() => musicBrainzLuceneQuery({ release: `a${String.fromCharCode(0xd800)}` }), inputFailure('invalidText'));
    assert.throws(() => musicBrainzLuceneQuery({ release: 'a\nb' }), inputFailure('invalidText'));
    assert.equal(cleanLookupTerm('  Hotel\u3000 California  '), 'Hotel California');
});

test('a link-like or malformed query is refused before any gate, DNS or request', async () => {
    const { fake, gate, musicBrainz, itunes, coverArt } = clients([]);
    await assert.rejects(musicBrainz.searchReleases({ release: 'https://musicbrainz.org/release/x' }, call()), inputFailure('url'));
    await assert.rejects(musicBrainz.searchRecordings({ recording: 'www.example.test' }, call()), inputFailure('url'));
    await assert.rejects(musicBrainz.lookupRelease('not-an-mbid', call()), inputFailure('identifier'));
    await assert.rejects(musicBrainz.browseReleaseGroupReleases('00000000-0000-0000-0000-000000000000', call()), inputFailure('identifier'));
    await assert.rejects(musicBrainz.lookupIsrc('JP-Y39', call()), inputFailure('identifier'));
    await assert.rejects(itunes.searchCollections('https://music.apple.com/x', 'us', call()), inputFailure('url'));
    await assert.rejects(itunes.lookupUpc('075596050921', 'us', call()), inputFailure('identifier'));
    await assert.rejects(coverArt.listRelease('../release', call()), inputFailure('identifier'));
    assert.equal(gate.acquisitions, 0); assert.deepEqual(fake.lookups, []); assert.deepEqual(fake.requests, []);
});

test('recorded MusicBrainz searches, lookups, browse and ISRC answers parse completely', async () => {
    // The recorded first page of the Hotel California search (limit=25) is served for the run's 100-release URL: parsing is the same.
    const [hotel, ...others] = exchangesOf('musicbrainz/release-search-hotel-california.json', `musicbrainz/release-${blueArchiveCd}.json`,
        'musicbrainz/release-0ea3b00b-a9a3-46e1-b1e2-f1e7697e8878.json', 'musicbrainz/recording-search-pandora-call.json',
        'musicbrainz/browse-release-group-836f349a.json', 'musicbrainz/isrc-JPY392200483.json');
    assert.ok(hotel.url.endsWith('&limit=25'));
    const { musicBrainz, fake } = clients([{ ...hotel, url: musicBrainzUrls.releaseSearch({ release: 'Hotel California', artist: 'Eagles' }).href }, ...others]);
    const search = await musicBrainz.searchReleases({ release: 'Hotel California', artist: 'Eagles' }, call());
    assert.equal(search.count, 83); assert.equal(search.releases.length, 25);
    assert.ok(search.releases.every(release => release.score !== null && normalizeMusicBrainzId(release.releaseId)));

    const cd = (await musicBrainz.lookupRelease(blueArchiveCd.toUpperCase(), call()))!;
    assert.deepEqual(cd.media.map(medium => medium.tracks.length), [20, 19]);
    assert.deepEqual(cd.artistCredit.map(credit => [credit.name, credit.joinPhrase]), [['Mitsukiyo', '、'], ['KARUT', '、'], ['Nor', '']]);
    assert.equal(cd.artistCredit[0].artistName, 'ミツキヨ');
    assert.equal(cd.labels[0].name, '株式会社Yostar');
    assert.deepEqual(cd.groupFirstReleaseDate, { year: 2022, month: 3, day: 24 });
    assert.equal(cd.frontArtwork, true); assert.equal(cd.barcode, '4582579942951');

    const bootleg = (await musicBrainz.lookupRelease('0ea3b00b-a9a3-46e1-b1e2-f1e7697e8878', call()))!;
    assert.equal(bootleg.labels[0].labelId, MUSICBRAINZ_PLACEHOLDER_IDS.noLabel); assert.equal(bootleg.labels[0].name, '[no label]');

    const recordings = await musicBrainz.searchRecordings({ recording: 'パンドラコール', artist: 'ヰ世界情緒' }, call());
    assert.equal(recordings.recordings.length, 4);
    assert.equal(recordings.recordings.filter(hit => hit.lengthMs === null).length, 1);
    assert.ok(recordings.recordings.some(hit => hit.releases.some(release => release.releaseId.startsWith('8659aff4'))));

    const browse = await musicBrainz.browseReleaseGroupReleases('836f349a-0434-3e8b-a0bc-261f77a9f99c', call());
    assert.equal(browse.length, 69); assert.ok(browse.every(release => release.trackCount > 0 && release.artistCredit.length));

    const isrc = (await musicBrainz.lookupIsrc('jp-y39-22-00483', call()))!;
    assert.equal(isrc.isrc, 'JPY392200483'); assert.equal(isrc.recordings.length, 2);
    assert.ok(fake.requests.every(request => request.headers['User-Agent'] === 'Finitude/1.0 ( lookup-operator@example.test )'));
    assert.deepEqual(Object.keys(fake.requests[0].headers), ['Accept', 'Accept-Encoding', 'User-Agent']);
});

test('the live smoke\'s recorded searches parse: "Sound Track" finds nothing, "Soundtrack" and the subtitle find the CD and digital editions, and the digital Hotel California parses', async () => {
    const { musicBrainz } = clients(exchangesOf('musicbrainz/release-search-blue-archive-sound-track.json', 'musicbrainz/release-search-blue-archive-normalized.json',
        'musicbrainz/release-search-blue-archive-subtitle.json', 'musicbrainz/release-fa7d3357-f3e9-4da5-ad70-09c05ef8207f.json'));
    const tag = 'Blue Archive Original Sound Track Vol.1 ~Longing for the memorable days~';
    for (const extra of [{}, { artist: 'ミツキヨ、KARUT、Nor' }, { label: '株式会社Yostar' }]) {
        assert.deepEqual(await musicBrainz.searchReleases({ release: tag, ...extra }, call()), { count: 0, releases: [] }, JSON.stringify(extra));
    }
    const found = async (query: { release: string; artist?: string; label?: string }) => (await musicBrainz.searchReleases(query, call())).releases.map(release => [release.releaseId.slice(0, 8), release.trackCount]);
    assert.deepEqual(await found({ release: 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~' }), [['8baecda4', 39], ['8f032fff', 39]]);
    assert.deepEqual(await found({ release: 'Blue Archive Original Soundtrack Vol.1 ~Longing for the memorable days~', label: '株式会社Yostar' }), [['8baecda4', 39], ['8f032fff', 39]]);
    assert.deepEqual(await found({ release: 'Longing for the memorable days' }), [['8baecda4', 39], ['8f032fff', 39]]);
    assert.deepEqual(await found({ release: 'Longing for the memorable days', artist: 'ミツキヨ、KARUT、Nor' }), [['8f032fff', 39]]);
    const digital = (await musicBrainz.lookupRelease('fa7d3357-f3e9-4da5-ad70-09c05ef8207f', call()))!;
    assert.deepEqual([digital.title, digital.trackCount, digital.labels.map(label => label.name), digital.media[0].tracks.every(track => track.lengthMs !== null)],
        ['Hotel California', 9, ['Elektra', 'Rhino'], true]);
});

test('recorded release searches are complete pages, so they answer the 100-release page alike; the derived Hotel California page is the recorded first page and the digital edition', () => {
    type Page = { count: number; releases: { id: string; 'track-count'?: number }[] };
    const searches = loadLookupFixtures('musicbrainz');
    for (const [name, file] of searches) for (const exchange of file.exchanges.filter(item => item.url.includes('/ws/2/release?query=') && item.status === 200 && !file.synthetic)) {
        const body = exchange.body as Page, page = new URL(exchange.url).searchParams.get('limit');
        // Every recorded search but Hotel California (83 hits, recorded with a 25-release page) is a complete page.
        if (name === 'release-search-hotel-california.json') assert.deepEqual([page, body.count, body.releases.length], ['25', 83, 25]);
        else assert.ok(page === '100' && body.count <= body.releases.length, name);
    }
    const recorded = loadLookupFixture('musicbrainz/release-search-hotel-california.json').exchanges[0].body as Page;
    const derived = loadLookupFixture('musicbrainz/synthetic-release-search-hotel-california-page.json');
    const browsed = loadLookupFixture('musicbrainz/browse-release-group-836f349a.json').exchanges.flatMap(exchange => (exchange.body as { releases: { id: string }[] }).releases);
    const page = derived.exchanges[0].body as Page;
    assert.deepEqual([derived.synthetic, derived.exchanges.length, derived.exchanges[0].url, page.count, page.releases.slice(0, 25)],
        [true, 1, musicBrainzUrls.releaseSearch({ release: 'Hotel California', artist: 'Eagles' }).href, 26, recorded.releases]);
    const digital = page.releases[25];
    assert.deepEqual([digital.id, digital['track-count'], browsed.some(release => release.id === digital.id), recorded.releases.some(release => release.id === digital.id)],
        ['fa7d3357-f3e9-4da5-ad70-09c05ef8207f', 9, true, false]);
    assert.equal(parseMusicBrainzReleaseSearch(page).releases.length, 26);
});

test('a 503 with Retry-After 0 waits the one-second minimum in wait mode and succeeds, and fails at once as rateLimited in busy mode', async () => {
    const file = 'musicbrainz/synthetic-503-retry-after-0-then-200.json';
    const query = { release: 'Synthetic Album' };
    const waiting = clients(exchangesOf(file));
    assert.equal((await waiting.musicBrainz.searchReleases(query, call())).count, 1);
    assert.deepEqual([waiting.sleeps, waiting.fake.requests.length, waiting.gate.releases], [[1000], 2, [{ backoffMs: 1000 }, undefined]]);
    const busy = clients(exchangesOf(file));
    await assert.rejects(busy.musicBrainz.searchReleases(query, call('busy')), error => {
        sourceFailure('musicbrainz', 'rateLimited')(error);
        assert.equal((error as MetadataLookupSourceError).retryAfterMs, 1000); return true;
    });
    assert.deepEqual([busy.sleeps, busy.fake.requests.length], [[], 1]);
});

test('a 404 lookup is null and cached, so a repeat sends nothing', async () => {
    const releaseId = '00000000-0000-4000-8000-000000000404';
    const { cache, sets } = spyCache();
    const { musicBrainz, fake, gate } = clients([{ url: musicBrainzUrls.release(releaseId).href, status: 404, headers: { 'content-type': 'application/json' }, bodyText: '{"error":"Not Found"}' }], { cache });
    assert.equal(await musicBrainz.lookupRelease(releaseId, call()), null);
    assert.equal(await musicBrainz.lookupRelease(releaseId, call()), null);
    assert.equal(fake.requests.length, 1); assert.equal(gate.acquisitions, 1); assert.equal(sets.length, 1);
    assert.equal(fake.bodies[0].destroyed, true);
});

test('503 honors Retry-After through the injected sleep, pushes the gate backoff and succeeds on the second attempt', async () => {
    const file = 'musicbrainz/synthetic-503-retry-after-then-200.json';
    const { musicBrainz, fake, sleeps, gate } = clients(exchangesOf(file));
    const release = (await musicBrainz.lookupRelease(syntheticId(file), call()))!;
    assert.equal(release.title, 'Synthetic Release');
    assert.deepEqual(sleeps, [2000]); assert.equal(fake.requests.length, 2);
    assert.deepEqual(gate.releases, [{ backoffMs: 2000 }, undefined]);
});

test('three 503 answers end as rateLimited after the bounded schedule, and busy mode tries once without sleeping', async () => {
    const file = 'musicbrainz/synthetic-503-three-times.json';
    const { cache, sets } = spyCache();
    const waiting = clients(exchangesOf(file), { cache });
    await assert.rejects(waiting.musicBrainz.lookupRelease(syntheticId(file), call()), error => {
        sourceFailure('musicbrainz', 'rateLimited')(error);
        assert.equal((error as MetadataLookupSourceError).retryAfterMs, 5000); return true;
    });
    assert.deepEqual(waiting.sleeps, [2000, 5000]); assert.equal(waiting.fake.requests.length, 3); assert.deepEqual(sets, []);
    assert.deepEqual(waiting.gate.releases, [{ backoffMs: 2000 }, { backoffMs: 5000 }, { backoffMs: 5000 }]);
    const busy = clients(exchangesOf(file));
    await assert.rejects(busy.musicBrainz.lookupRelease(syntheticId(file), call('busy')), error => {
        sourceFailure('musicbrainz', 'rateLimited')(error);
        assert.equal((error as MetadataLookupSourceError).retryAfterMs, 2000); return true;
    });
    assert.deepEqual(busy.sleeps, []); assert.equal(busy.fake.requests.length, 1);
});

test('Retry-After accepts delta-seconds and HTTP-dates within one to thirty seconds', () => {
    const now = Date.parse('Sun, 18 Oct 2026 10:00:00 GMT');
    assert.equal(parseRetryAfter('2', now), 2000);
    assert.equal(parseRetryAfter('0', now), 1000);
    assert.equal(parseRetryAfter('600', now), 30_000);
    assert.equal(parseRetryAfter('Sun, 18 Oct 2026 10:00:07 GMT', now), 7000);
    assert.equal(parseRetryAfter('Sun, 18 Oct 2026 09:00:00 GMT', now), 1000);
    for (const value of [undefined, '', '-1', '1.5', 'soon', ['2'], 'x'.repeat(65)]) assert.equal(parseRetryAfter(value, now), null);
});

test('every malformed synthetic MusicBrainz answer is invalid or unavailable, never a no-match, and is not cached', async () => {
    const expectations: [string, 'invalidResponse' | 'unavailable'][] = [
        ['synthetic-declared-oversize.json', 'unavailable'], ['synthetic-streamed-oversize.json', 'unavailable'],
        ['synthetic-truncated.json', 'unavailable'], ['synthetic-invalid-utf8.json', 'invalidResponse'],
        ['synthetic-duplicate-keys.json', 'invalidResponse'], ['synthetic-depth-21.json', 'invalidResponse'],
        ['synthetic-text-html.json', 'invalidResponse'], ['synthetic-gzip.json', 'invalidResponse'],
        ['synthetic-lone-surrogate.json', 'invalidResponse'], ['synthetic-overlong-title.json', 'invalidResponse'],
        ['synthetic-bad-mbid.json', 'invalidResponse'], ['synthetic-bad-date.json', 'invalidResponse'],
        ['synthetic-redirect-off-host.json', 'unavailable'], ['synthetic-four-redirects.json', 'unavailable']
    ];
    for (const [name, failure] of expectations) {
        const { cache, sets } = spyCache();
        const { musicBrainz, fake } = clients(exchangesOf(`musicbrainz/${name}`), { cache });
        await assert.rejects(musicBrainz.lookupRelease(syntheticId(`musicbrainz/${name}`), call()), sourceFailure('musicbrainz', failure), name);
        assert.deepEqual(sets, [], name);
        assert.ok(fake.bodies.every(body => body.destroyed || body.readableEnded), name);
    }
    const { musicBrainz } = clients(exchangesOf('musicbrainz/synthetic-wrong-type.json'));
    await assert.rejects(musicBrainz.searchReleases({ release: 'Synthetic Wrong Type' }, call()), sourceFailure('musicbrainz', 'invalidResponse'));
});

test('redirects are refused off host before a second lookup and after three hops', async () => {
    const offHost = clients(exchangesOf('musicbrainz/synthetic-redirect-off-host.json'));
    await assert.rejects(offHost.musicBrainz.lookupRelease(syntheticId('musicbrainz/synthetic-redirect-off-host.json'), call()));
    assert.deepEqual(offHost.fake.lookups, ['musicbrainz.org']); assert.equal(offHost.fake.requests.length, 1);
    const tooMany = clients(exchangesOf('musicbrainz/synthetic-four-redirects.json'));
    await assert.rejects(tooMany.musicBrainz.lookupRelease(syntheticId('musicbrainz/synthetic-four-redirects.json'), call()));
    assert.equal(tooMany.fake.requests.length, 4);
});

test('unknown fields are dropped and a placeholder barcode becomes no barcode', async () => {
    const { musicBrainz } = clients(exchangesOf('musicbrainz/synthetic-unknown-fields.json', 'musicbrainz/synthetic-placeholder-barcode.json'));
    const release = (await musicBrainz.lookupRelease(syntheticId('musicbrainz/synthetic-unknown-fields.json'), call()))!;
    const serialized = JSON.stringify(release);
    for (const dropped of ['unexpected', 'asin', 'packaging', 'pregap', 'Hidden', 'video']) assert.equal(serialized.includes(dropped), false, dropped);
    assert.deepEqual(release.media[0].tracks[0].isrcs, ['USAAA2000001']);
    const placeholder = (await musicBrainz.lookupRelease(syntheticId('musicbrainz/synthetic-placeholder-barcode.json'), call()))!;
    assert.equal(placeholder.barcode, null); assert.equal(placeholder.barcodeText, '0000000000000');
});

test('artist and label alias lookups have fixed URLs, refuse a malformed ID before sending, and keep names in a fixed order without search hints', async () => {
    const artist = '00000000-0000-4000-8000-0000000000a1', label = '00000000-0000-4000-8000-0000000000b1';
    assert.equal(musicBrainzUrls.artistAliases(artist.toUpperCase()).href, `https://musicbrainz.org/ws/2/artist/${artist}?inc=aliases&fmt=json`);
    assert.equal(musicBrainzUrls.labelAliases(label).href, `https://musicbrainz.org/ws/2/label/${label}?inc=aliases&fmt=json`);
    for (const value of ['not-an-id', '00000000-0000-0000-0000-000000000000', `${artist}/../release`]) {
        assert.throws(() => musicBrainzUrls.artistAliases(value), inputFailure('identifier'), value);
        assert.throws(() => musicBrainzUrls.labelAliases(value), inputFailure('identifier'), value);
    }
    const alias = (name: string, type: string | null, primary: boolean | null = null) => ({ name, 'sort-name': name, type, primary, locale: null });
    const body = { id: artist, name: 'Synthetic Artist', disambiguation: 'ignored', aliases: [alias('Zeta', 'Artist name'), alias('Synthetic Artiste', 'Search hint'), alias('beta', null),
        alias('Ālpha', 'Artist name', true), alias('SYNTHETIC ARTIST', 'Artist name'), alias('Omega', 'Legal name', true), alias('  ', 'Artist name'), alias('Hidden\u200bName', null)] };
    assert.deepEqual(parseMusicBrainzEntityAliases(body, artist), { id: artist, names: ['Synthetic Artist', 'Omega', 'Ālpha', 'beta', 'Zeta'] });
    // A merged entity answered under another ID gives no names; a response without aliases gives its own name only.
    assert.equal(parseMusicBrainzEntityAliases({ ...body, id: label }, artist), null);
    assert.deepEqual(parseMusicBrainzEntityAliases({ id: artist, name: 'Only' }, artist), { id: artist, names: ['Only'] });
    const many = { ...body, aliases: Array.from({ length: 40 }, (_unused, index) => alias(`Name ${String(index).padStart(2, '0')}`, 'Artist name')) };
    assert.equal(parseMusicBrainzEntityAliases(many, artist)!.names.length, 32);
    for (const invalid of [{ ...body, id: 'x' }, { ...body, name: 7 }, { ...body, aliases: [{ name: 7 }] }, { ...body, aliases: 'x' }, null]) {
        assert.throws(() => parseMusicBrainzEntityAliases(invalid, artist), JSON.stringify(invalid)?.slice(0, 40));
    }
    // Through the client: 404 is null, an answer is parsed, and both kinds use their own URL.
    const { musicBrainz, fake } = clients([{ url: musicBrainzUrls.artistAliases(artist).href, status: 200, headers: { 'content-type': 'application/json' }, body },
        { url: musicBrainzUrls.labelAliases(label).href, status: 404, headers: { 'content-type': 'application/json' }, bodyText: '{"error":"Not Found"}' }]);
    assert.deepEqual(await musicBrainz.lookupAliases('artist', artist, call()), { id: artist, names: ['Synthetic Artist', 'Omega', 'Ālpha', 'beta', 'Zeta'] });
    assert.equal(await musicBrainz.lookupAliases('label', label, call()), null);
    assert.equal(fake.requests.length, 2);
    await assert.rejects(musicBrainz.lookupAliases('artist', 'bad', call()), inputFailure('identifier'));
    assert.equal(fake.requests.length, 2);
});

test('identifier formats are checked before use', () => {
    assert.equal(normalizeMusicBrainzId('8BAECDA4-F155-40F6-A173-8F6B98CEDE5B'), blueArchiveCd);
    for (const value of ['00000000-0000-0000-0000-000000000000', '8baecda4f15540f6a1738f6b98cede5b', `{${blueArchiveCd}}`, `${blueArchiveCd.slice(0, -1)}g`, 42, null]) {
        assert.equal(normalizeMusicBrainzId(value), null, String(value));
    }
    assert.deepEqual(normalizeGtin('075596050920'), { digits: '075596050920', gtin14: '00075596050920' });
    assert.equal(normalizeGtin('0075596050920')!.gtin14, normalizeGtin('075596050920')!.gtin14);
    assert.equal(normalizeGtin('0 75596-05092 0')!.digits, '075596050920');
    for (const valid of ['4582579942951', '96385074', '036000291452', '00036000291452']) assert.ok(normalizeGtin(valid), valid);
    for (const invalid of ['075596050921', '0000000000000', '00000000', '7559605092', '07559605092a', '', 75596050920, null]) assert.equal(normalizeGtin(invalid), null, String(invalid));
    assert.equal(normalizeIsrc('jp-y39-22-00483'), 'JPY392200483');
    for (const invalid of ['JPY39220048', 'J1Y392200483', 'JPY39220048X', '', null]) assert.equal(normalizeIsrc(invalid), null, String(invalid));
    assert.equal(normalizeItunesId('1689358563'), '1689358563'); assert.equal(normalizeItunesId(1689358563), '1689358563');
    for (const invalid of ['0123', '', '1'.repeat(13), -1, 0, 1.5, '12a', null]) assert.equal(normalizeItunesId(invalid), null, String(invalid));
    assert.equal(normalizeCoverArtImageId(32500502536), '32500502536'); assert.equal(normalizeCoverArtImageId('9786783001'), '9786783001');
    for (const invalid of ['0', 0, -5, 1.5, 'abc', '1'.repeat(21), null]) assert.equal(normalizeCoverArtImageId(invalid), null, String(invalid));
});

test('iTunes accepts text/javascript, drops preview and store links, keeps allowlisted artwork and sends no contact', async () => {
    const { itunes, fake } = clients(exchangesOf('itunes/search-us-album-hotel-california.json', 'itunes/search-jp-song-pandora-call.json',
        'itunes/lookup-jp-1689358563.json', 'itunes/lookup-us-upc-075596050920.json', 'itunes/search-jp-song-pandora-call-romanized.json'));
    const albums = await itunes.searchCollections('Hotel California Eagles', 'us', call());
    assert.equal(albums.collections.length, 25); assert.equal(albums.collections[0].collectionName, 'Hotel California');
    assert.match(albums.collections[0].artworkUrl!, /^https:\/\/is[1-5]-ssl\.mzstatic\.com\//);
    const songs = await itunes.searchSongs('パンドラコール', 'jp', call());
    const single = songs.tracks.find(track => track.artistName === 'ヰ世界情緒' && track.collectionName?.startsWith('パンドラコール'))!;
    assert.equal(single.trackTimeMillis, 217030);
    const lookup = (await itunes.lookupCollection(single.collectionId, 'jp', call()))!;
    assert.equal(lookup.collections.length, 1); assert.equal(lookup.tracks.length, 1);
    assert.deepEqual(lookup.collections[0].releaseDate && Object.keys(lookup.collections[0].releaseDate), ['year', 'month', 'day']);
    const upc = (await itunes.lookupUpc('075596050920', 'us', call()))!;
    assert.ok(upc.collections.length >= 1 && upc.tracks.length >= 1);
    const romanized = await itunes.searchSongs('Pandora Call', 'jp', call());
    assert.ok(romanized.tracks.some(track => track.trackName === 'パンドラコール'));
    for (const output of [albums, songs, lookup, upc, romanized]) {
        const serialized = JSON.stringify(output);
        for (const forbidden of ['previewUrl', 'ViewUrl', 'music.apple.com', 'audio-ssl', 'itunes.apple.com']) assert.equal(serialized.includes(forbidden), false, forbidden);
    }
    assert.ok(fake.requests.every(request => new URL(request.url).hostname === METADATA_LOOKUP_HOSTS.itunes));
    // Apple does not ask for a contact, so the operator's never reaches it.
    assert.ok(fake.requests.length >= 5 && fake.requests.every(request => request.headers['User-Agent'] === 'Finitude/1.0'));
});

test('iTunes storefronts are fixed and ordered by script', () => {
    assert.deepEqual(itunesStorefrontsForText('パンドラコール'), ['jp', 'us']);
    assert.deepEqual(itunesStorefrontsForText('ヰ世界情緒'), ['jp', 'us']);
    assert.deepEqual(itunesStorefrontsForText('블루 아카이브'), ['kr', 'us']);
    assert.deepEqual(itunesStorefrontsForText('色彩'), ['jp', 'tw', 'us']);
    assert.deepEqual(itunesStorefrontsForText('Hotel California'), ['us', 'jp']);
    assert.throws(() => itunesUrls.search('Hotel California', 'gb', 'album'), inputFailure('identifier'));
    assert.throws(() => itunesUrls.lookupId('1689358563', 'JP'), inputFailure('identifier'));
});

test('UPC lookups choose storefronts by the GS1 prefix of a valid barcode, and the artwork address survives only on the fixed artwork hosts', () => {
    const order = (barcode: string) => itunesStorefrontsForBarcode(normalizeGtin(barcode)!);
    // Japanese JAN prefixes (450–459, 490–499), Korea (880), Taiwan (471), anything else in the us storefront first.
    assert.deepEqual([order('4582579942951'), order('4902102072915'), order('4500000000001'), order('4999999999999')], [['jp', 'us'], ['jp', 'us'], ['jp', 'us'], ['jp', 'us']]);
    assert.deepEqual([order('8801234567893'), order('4710000000004'), order('075596050920'), order('4006381333931'), order('4600000000008')],
        [['kr', 'us'], ['tw', 'us'], ['us', 'jp'], ['us', 'jp'], ['us', 'jp']]);
    assert.deepEqual([itunesArtworkAddress('https://is5-ssl.mzstatic.com/image/thumb/x/100x100bb.jpg'), itunesArtworkAddress('https://is6-ssl.mzstatic.com/x.jpg'),
        itunesArtworkAddress('http://is1-ssl.mzstatic.com/x.jpg'), itunesArtworkAddress(7)], ['https://is5-ssl.mzstatic.com/image/thumb/x/100x100bb.jpg', null, null, null]);
});

test('iTunes 403 and 429 are rateLimited, and an empty lookup is null', async () => {
    const forbidden = clients(exchangesOf('itunes/synthetic-403.json'));
    await assert.rejects(forbidden.itunes.searchCollections('Synthetic Forbidden', 'us', call('busy')), sourceFailure('itunes', 'rateLimited'));
    // The pushed backoff then holds the source: a submitted lookup is busy rather than sent.
    await assert.rejects(forbidden.itunes.searchCollections('Synthetic Forbidden', 'us', call('busy')), sourceFailure('itunes', 'busy'));
    assert.equal(forbidden.fake.requests.length, 1);
    const limited = clients(exchangesOf('itunes/synthetic-429.json'));
    await assert.rejects(limited.itunes.searchCollections('Synthetic Rate Limited', 'us', call('busy')), sourceFailure('itunes', 'rateLimited'));
    const empty = clients(exchangesOf('itunes/synthetic-empty-result.json'));
    assert.equal(await empty.itunes.lookupCollection('1000000001', 'us', call()), null);
});

test('the Cover Art Archive listing follows its three allowlisted hops and returns no URL', async () => {
    const releaseId = '83afdb26-9c27-4ec6-ad70-25b8cb897a31';
    const { coverArt, fake } = clients(exchangesOf(`coverartarchive/listing-${releaseId}.json`, 'coverartarchive/listing-24ae881f-7cb3-4c43-b80e-70332cd7c50d.json',
        'coverartarchive/synthetic-500.json', 'coverartarchive/synthetic-release-mismatch.json', 'coverartarchive/synthetic-path-other-mbid.json'));
    const listing = (await coverArt.listRelease(releaseId, call()))!;
    assert.equal(listing.releaseId, releaseId);
    assert.ok(listing.images.some(image => image.front && image.types.includes('Front')));
    assert.ok(listing.images.every(image => /^\d+$/.test(image.imageId) && image.sizes.every(size => [250, 500, 1200].includes(size))));
    assert.doesNotMatch(JSON.stringify(listing), /https?:|archive\.org/);
    const hosts = fake.requests.map(request => new URL(request.url).hostname);
    assert.equal(hosts[0], 'coverartarchive.org'); assert.equal(hosts[1], 'archive.org'); assert.match(hosts[2], METADATA_LOOKUP_HOSTS.archiveStorage);
    assert.ok(fake.requests.every(request => request.headers['User-Agent'] === 'Finitude/1.0 ( lookup-operator@example.test )'),
        'Cover Art Archive, the MusicBrainz artwork service, and its archive.org hops carry the contact');
    assert.equal(await coverArt.listRelease(hotelCalifornia, call()), null);
    await assert.rejects(coverArt.listRelease('00000000-0000-4000-8000-000000000020', call()), sourceFailure('coverartarchive', 'unavailable'));
    await assert.rejects(coverArt.listRelease('00000000-0000-4000-8000-000000000021', call()), sourceFailure('coverartarchive', 'invalidResponse'));
    const before = fake.lookups.length;
    await assert.rejects(coverArt.listRelease('00000000-0000-4000-8000-000000000022', call()), sourceFailure('coverartarchive', 'unavailable'));
    assert.equal(fake.lookups.length - before, 1, 'a hop bound to another MBID is refused before DNS');
});

test('each Cover Art Archive hop is bound to its host and to the requested MBID', () => {
    const id = blueArchiveCd, other = hotelCalifornia;
    const allowed = coverArtDestination(id);
    const accepted: [string, number][] = [[`https://coverartarchive.org/release/${id}`, 0], [`https://coverartarchive.org/release/${id}/`, 2],
        [`https://archive.org/download/mbid-${id}/index.json`, 1], [`https://dn720704.ca.archive.org/0/items/mbid-${id}/index.json`, 2],
        [`https://ia800101.us.archive.org/12/items/mbid-${id}/index.json`, 1]];
    for (const [url, hop] of accepted) assert.equal(allowed(new URL(url), hop)?.href, url);
    const refused: [string, number][] = [[`https://archive.org/download/mbid-${id}/index.json`, 0], [`https://coverartarchive.org/release/${other}`, 0],
        [`https://archive.org/download/mbid-${other}/index.json`, 1], [`https://dn720704.ca.archive.org/0/items/mbid-${other}/index.json`, 2],
        [`https://evil.archive.org/0/items/mbid-${id}/index.json`, 2], [`https://dn720704.ca.archive.org.example.test/0/items/mbid-${id}/index.json`, 2],
        [`http://archive.org/download/mbid-${id}/index.json`, 1], [`https://archive.org/download/mbid-${id}/index.json?x=1`, 1],
        [`https://archive.org/download/mbid-${id}/other.json`, 1], [`https://coverartarchive.org/release/${id}/front`, 1]];
    for (const [url, hop] of refused) assert.equal(allowed(new URL(url), hop), null, url);
});

test('the response cache serves hits without requests, expires, evicts by entries and bytes, and keys storefronts apart', async () => {
    let now = 0;
    const cache = createLookupResponseCache({ maxEntries: 2, maxBytes: 100, ttlMs: 1000, now: () => now });
    cache.set('a', { value: 1 }, 10); cache.set('b', null, 10);
    assert.deepEqual(cache.get('a'), { value: { value: 1 } }); assert.deepEqual(cache.get('b'), { value: null });
    assert.ok(Object.isFrozen((cache.get('a')!.value as object)));
    cache.set('c', 3, 10);
    assert.equal(cache.get('b'), undefined, 'least recently used entry is evicted');
    cache.set('d', 4, 95);
    assert.equal(cache.get('a'), undefined); assert.equal(cache.get('c'), undefined); assert.deepEqual(cache.get('d'), { value: 4 });
    cache.set('huge', 5, 101); assert.equal(cache.get('huge'), undefined);
    now = 1000; assert.equal(cache.get('d'), undefined, 'expired');
    cache.set('e', 6, 1); cache.clear(); assert.equal(cache.get('e'), undefined);

    const body = loadLookupFixture('itunes/search-us-album-hotel-california.json').exchanges[0];
    const shared = createLookupResponseCache();
    const us = itunesUrls.search('Hotel California Eagles', 'us', 'album').href, jp = itunesUrls.search('Hotel California Eagles', 'jp', 'album').href;
    const { itunes, fake, gate } = clients([{ ...body, url: us }, { ...body, url: jp }], { cache: shared });
    await itunes.searchCollections('Hotel California Eagles', 'us', call());
    await itunes.searchCollections('Hotel California Eagles', 'us', call());
    await itunes.searchCollections('Hotel California Eagles', 'jp', call());
    assert.deepEqual(fake.requests.map(request => request.url), [us, jp]); assert.equal(gate.acquisitions, 2);
});

test('an unconfigured lookup sends nothing: no cache read, gate, DNS or request', async () => {
    for (const configuration of [() => ({ available: false as const, reason: 'contactMissing' as const }), undefined]) {
        const { cache, sets } = spyCache();
        let reads = 0;
        const counting: LookupResponseCache = { ...cache, get: key => { reads++; return cache.get(key); } };
        const { musicBrainz, itunes, coverArt, fake, gate } = clients(exchangesOf(`musicbrainz/release-${hotelCalifornia}.json`), { cache: counting, configuration });
        await assert.rejects(musicBrainz.lookupRelease(hotelCalifornia, call()), sourceFailure('musicbrainz', 'notConfigured'));
        await assert.rejects(itunes.searchSongs('パンドラコール', 'jp', call()), sourceFailure('itunes', 'notConfigured'));
        await assert.rejects(coverArt.listRelease(hotelCalifornia, call()), sourceFailure('coverartarchive', 'notConfigured'));
        assert.equal(gate.acquisitions, 0); assert.deepEqual(fake.lookups, []); assert.deepEqual(fake.requests, []);
        assert.equal(reads, 0); assert.deepEqual(sets, []);
    }
});

test('fixtures hold only allowlisted public exchanges, under 2 MiB, and no test references the recorder', () => {
    const recordedHeaders = new Set(['content-type', 'location', 'retry-after']);
    const syntheticHeaders = new Set([...recordedHeaders, 'content-length', 'content-encoding']);
    const exchangeKeys = new Set(['url', 'status', 'headers', 'body', 'bodyText', 'bodyBase64', 'bodyPadding']);
    const allowedHost = (host: string) => fixedHosts.includes(host) || METADATA_LOOKUP_HOSTS.archiveStorage.test(host);
    let total = 0;
    const files = allLookupFixtureFiles();
    assert.ok(files.filter(entry => !entry.file.synthetic).length >= 45);
    for (const { path: file, file: fixture } of files) {
        const text = readFileSync(path.join(fixtureRoot, file), 'utf8');
        total += Buffer.byteLength(text);
        assert.doesNotMatch(text, /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+\.[A-Za-z]{2,}/, `${file} contains an email-like string`);
        assert.doesNotMatch(text, /previewUrl|trackViewUrl|collectionViewUrl|artistViewUrl|audio-ssl|user-agent|authorization|cookie/i, file);
        assert.ok(text.endsWith('}\n') && !text.includes('\r'), `${file} is LF JSON with a trailing newline`);
        for (const exchange of fixture.exchanges) {
            assert.ok(Object.keys(exchange).every(key => exchangeKeys.has(key)), file);
            assert.ok(Object.keys(exchange.headers).every(key => (fixture.synthetic ? syntheticHeaders : recordedHeaders).has(key)), file);
            assert.ok(allowedHost(new URL(exchange.url).hostname), `${file}: ${exchange.url}`);
        }
    }
    total += statSync(path.join(fixtureRoot, 'manifest.json')).size;
    assert.ok(total <= 2 * 1024 * 1024, `fixtures total ${total} bytes`);
    const manifest = JSON.parse(readFileSync(path.join(fixtureRoot, 'manifest.json'), 'utf8'));
    assert.deepEqual(Object.keys(manifest).sort(), ['probes', 'recordedAt', 'recorder', 'userAgentProduct']);
    assert.equal(manifest.userAgentProduct, 'ArchtreeMetadataFixtureRecorder/0.1');
    // Every recorded file is a described probe, listed once in sorted order; synthetic files are described in themselves instead.
    const probes = (manifest.probes as { file: string; description: string }[]).map(probe => probe.file);
    assert.deepEqual(probes, files.filter(entry => !entry.file.synthetic).map(entry => entry.path).sort());
    assert.ok((manifest.probes as { description: unknown }[]).every(probe => typeof probe.description === 'string' && probe.description.length > 0));
    assert.ok(files.every(entry => typeof entry.file.description === 'string' && entry.file.description.length > 0), 'every fixture says what it holds');

    const recorderName = ['record', 'metadata', 'lookup', 'fixtures'].join('-');
    const testRoot = fileURLToPath(new URL('..', import.meta.url));
    const sources = (directory: string): string[] => readdirSync(directory, { withFileTypes: true }).flatMap(entry =>
        entry.isDirectory() ? sources(path.join(directory, entry.name)) : /\.(?:ts|mjs|js)$/.test(entry.name) ? [path.join(directory, entry.name)] : []);
    for (const file of sources(testRoot)) assert.equal(readFileSync(file, 'utf8').includes(recorderName), false, file);
});

test('every request in this file went to a fixed lookup host', () => {
    // Runs last, so it sees every fake transport the tests above created.
    const hosts = new Set(allFakes.flatMap(fake => fake.requests.map(request => new URL(request.url).hostname)));
    assert.ok(hosts.size >= 4);
    for (const host of hosts) {
        assert.ok(fixedHosts.includes(host) || METADATA_LOOKUP_HOSTS.archiveStorage.test(host), host);
    }
});
